    users = _arni_users()
    if not users:
        st.error(T("Üyelik sistemi henüz ayarlanmadı. Streamlit Secrets bölümüne kullanıcı eklenmeli.", "Membership system is not configured yet. Add users in Streamlit Secrets."))
