# =========================================================
# BIST HISSE EVRENI - TEK MERKEZDEN, DINAMIK VE YEDEKLI
# =========================================================
# Eski sürümde yalnızca yaklaşık 50 kodluk sabit liste vardı.
# Bu nedenle AYDEM gibi tamamen geçerli BIST hisseleri aramada görünmüyordu.
# Yeni sistem:
#   1) Yerel güvenli çekirdek listeyi kullanır.
#   2) Uygulama açıldığında güncel BIST sembollerini harici sembol listesinden çeker.
#   3) Listeye girmemiş yeni bir kod yazılırsa Yahoo Finance .IS verisiyle canlı doğrular.
# Böylece tek bir eksik sabit kayıt tüm ARNI'yi bozmaz.

BIST_FALLBACK = {
    "A1CAP","ACSEL","ADEL","ADESE","ADGYO","AEFES","AFYON","AGESA","AGHOL","AGYO","AHGAZ",
    "AKBNK","AKCNS","AKENR","AKFGY","AKFYE","AKGRT","AKMGY","AKSA","AKSEN","AKSGY","AKSUE","AKYHO",
    "ALARK","ALBRK","ALCAR","ALCTL","ALFAS","ALGYO","ALKA","ALKIM","ALMAD","ANELE","ANGEN","ANHYT","ANSGR",
    "ARASE","ARCLK","ARDYZ","ARENA","ARSAN","ARZUM","ASELS","ASGYO","ASTOR","ASUZU","ATAGY","ATAKP","ATATP",
    "ATEKS","ATLAS","ATSYH","AVGYO","AVHOL","AVOD","AVTUR","AYCES","AYDEM","AYEN","AYES","AYGAZ","AZTEK",
    "BAGFS","BAKAB","BALAT","BANVT","BARMA","BASCM","BASGZ","BAYRK","BERA","BEYAZ","BFREN","BIENY","BIGCH",
    "BIMAS","BIOEN","BIZIM","BRSAN","CCOLA","CIMSA","DOAS","EKGYO","ENJSA","ENKAI","EREGL","FROTO","GARAN",
    "GESAN","GUBRF","HALKB","HATSN","HEKTS","ISCTR","KARSN","KCHOL","KONTR","KRDMD","MGROS","ODAS","OYAKC",
    "PETKM","PGSUS","SAHOL","SASA","SISE","SKYMD","SOKE","TABGD","TAVHL","TBORG","TCELL","THYAO","TKFEN",
    "TOASO","TSKB","TUPRS","ULKER","VAKBN","VESBE","YKBNK","YEOTK","ZOREN"
}

@st.cache_data(ttl=21600, show_spinner=False)
def bist_hisse_evreni():
    semboller=set(BIST_FALLBACK)
    # Güncel sembol havuzu. Ağ/servis sorunu olursa fallback ile uygulama çalışmaya devam eder.
    try:
        import json, urllib.request
        url=("https://raw.githubusercontent.com/ahmeterenodaci/"
             "Istanbul-Stock-Exchange--BIST--including-symbols-and-logos/"
             "main/without_logo.json")
        req=urllib.request.Request(url,headers={"User-Agent":"Mozilla/5.0 ARNI/1.0"})
        with urllib.request.urlopen(req,timeout=5) as r:
            data=json.loads(r.read().decode("utf-8"))
        for item in data:
            kod=str(item.get("symbol","")).strip().upper()
            if re.fullmatch(r"[A-Z0-9]{3,8}",kod):
                semboller.add(kod)
    except Exception:
        pass
    return sorted(semboller)

HISSELER=bist_hisse_evreni()
POPULER=["THYAO","TUPRS","ASELS","KCHOL","SAHOL","SISE","PETKM","TAVHL","ASTOR","ISCTR"]
ABD={"AAPL","TSLA","NVDA","MSFT","GOOGL","AMZN"}
ISIM_SOZLUGU={"tüpraş":"TUPRS","tupras":"TUPRS","aselsan":"ASELS","thy":"THYAO","türk hava yolları":"THYAO","turk hava yollari":"THYAO","akbank":"AKBNK","halkbank":"HALKB","iş bankası":"ISCTR","is bankasi":"ISCTR","garanti":"GARAN","pegasus":"PGSUS","ereğli":"EREGL","eregli":"EREGL","şişecam":"SISE","sisecam":"SISE","koç":"KCHOL","koc":"KCHOL","sabancı":"SAHOL","sabanci":"SAHOL","bim":"BIMAS","bimaş":"BIMAS","söke":"SOKE","soke":"SOKE","skymd":"SKYMD","astor":"ASTOR","petkim":"PETKM","tav":"TAVHL","tavhl":"TAVHL","tuborg":"TBORG","yeotk":"YEOTK","karsan":"KARSN","migros":"MGROS","aydem":"AYDEM","aydem yenilenebilir":"AYDEM"}


# --- ARNI KURUM / AKILLI PARA MOTORU ---
# Manuel kurum lot değişimi ile ikinci teyit skoru üretir.
# Pozitif lot = toplama/net alım, negatif lot = azaltma/net satış.
KURUM_AGIRLIKLARI = {
    "CITIBANK": 1.00, "BOFA": 1.00, "BANK OF AMERICA": 1.00,
    "IS YATIRIM": 0.90, "İŞ YATIRIM": 0.90,
    "YAPI KREDI YATIRIM": 0.88, "YAPI KREDİ YATIRIM": 0.88,
    "AK YATIRIM": 0.88, "GARANTI YATIRIM": 0.84, "GARANTİ YATIRIM": 0.84,
    "QNB YATIRIM": 0.82, "YATIRIM FINANSMAN": 0.80, "YATIRIM FİNANSMAN": 0.80,
    "TEB": 0.80, "HSBC": 0.80, "TERA YATIRIM": 0.78,
    "ZIRAAT YATIRIM": 0.75, "ZİRAAT YATIRIM": 0.75,
    "VAKIF YATIRIM": 0.72, "HALK YATIRIM": 0.70,
    "GEDIK YATIRIM": 0.68, "GEDİK YATIRIM": 0.68,
    "MIDAS": 0.65, "MİDAS": 0.65, "BULLS": 0.65,
    "A1 CAPITAL": 0.62, "MARBAS": 0.60, "MARBAŞ": 0.60,
    "DENIZ YATIRIM": 0.60, "DENİZ YATIRIM": 0.60,
}

def kurum_skoru_hesapla(kayitlar):
    if not kayitlar:
        return 50, "VERİ YOK", []
    ham=0.0; toplam_agirlik=0.0; detay=[]
    max_abs=max([abs(float(k.get("degisim_lot",0) or 0)) for k in kayitlar] + [1.0])
    for k in kayitlar:
        kurum=str(k.get("kurum","")).strip().upper()
        lot=float(k.get("degisim_lot",0) or 0)
        agir=KURUM_AGIRLIKLARI.get(kurum,0.50)
        norm=max(-1.0,min(1.0,lot/max_abs))
        katki=norm*agir
        ham+=katki; toplam_agirlik+=agir
        detay.append((kurum,lot,agir,katki))
    if toplam_agirlik<=0:
        return 50, "VERİ YOK", detay
    oran=ham/toplam_agirlik
    skor=int(round(max(0,min(100,50 + oran*50))))
    durum=("GÜÇLÜ GİRİŞ" if skor>=75 else "POZİTİF" if skor>=60 else
           "KARIŞIK" if skor>=45 else "ZAYIF" if skor>=30 else "GÜÇLÜ ÇIKIŞ")
    return skor,durum,detay

def kod_yap(girdi):
    if not girdi:return None
    girdi=str(girdi).strip()
    if not girdi:return None
    kod=ISIM_SOZLUGU.get(girdi.lower(),girdi.upper())
    kod=re.sub(r"[^A-Z0-9.]","",kod)
    if kod in ABD:return kod
    return kod if kod.endswith(".IS") else kod+".IS"

@st.cache_data(ttl=15,show_spinner=False)
def veri_getir(kod,gun=60):
    try:
        ticker=yf.Ticker(kod)

        # Ana günlük seri
        df=ticker.history(period=f"{gun}d",interval="1d",auto_adjust=False,actions=False)
        if df is None or df.empty:
            df=yf.download(kod,period=f"{gun}d",interval="1d",progress=False,auto_adjust=False,threads=False)
        if df is None or df.empty:
            return pd.DataFrame()
        if isinstance(df.columns,pd.MultiIndex):
            df.columns=df.columns.get_level_values(0)
        df=df.dropna(subset=["Close"]).copy()

        # En güncel seansı intraday veriden al. Böylece kapanmış/aktif gün
        # günlük seride henüz görünmüyorsa fiyat eski güne takılı kalmaz.
        try:
            intra=ticker.history(period="5d",interval="5m",auto_adjust=False,actions=False,prepost=False)
            if intra is not None and not intra.empty:
                intra=intra.dropna(subset=["Close"]).copy()
                if not intra.empty:
                    latest_day=intra.index[-1].date()
                    day_rows=intra[["Open","High","Low","Close","Volume"]].copy()
                    day_rows=day_rows[day_rows.index.date==latest_day]
                    if not day_rows.empty:
                        live_row={
                            "Open":float(day_rows["Open"].iloc[0]),
                            "High":float(day_rows["High"].max()),
                            "Low":float(day_rows["Low"].min()),
                            "Close":float(day_rows["Close"].iloc[-1]),
                            "Volume":float(day_rows["Volume"].fillna(0).sum()),
                        }
                        df_dates=[x.date() for x in df.index]
                        if latest_day in df_dates:
                            pos=df_dates.index(latest_day)
                            idx=df.index[pos]
                            for col,val in live_row.items():
                                if col in df.columns:
                                    df.at[idx,col]=val
                        elif latest_day>df.index[-1].date():
                            idx=pd.Timestamp(latest_day)
                            if getattr(df.index,"tz",None) is not None:
                                idx=idx.tz_localize(df.index.tz)
                            new_row={c:np.nan for c in df.columns}
                            new_row.update({k:v for k,v in live_row.items() if k in df.columns})
                            df.loc[idx]=new_row
        except Exception:
            pass

        return df.sort_index().dropna(subset=["Close"])
    except Exception:
        return pd.DataFrame()

@st.cache_data(ttl=3600, show_spinner=False)
def bist_kodu_gecerli_mi(kod):
    """ARNI ana listesinde olmasa bile gerçek BIST kodunu canlı veriden doğrular."""
    kod=re.sub(r"[^A-Z0-9]","",str(kod).upper())
    if not re.fullmatch(r"[A-Z0-9]{3,8}",kod):
        return False
    if kod in HISSELER:
        return True
    try:
        d=veri_getir(kod+".IS",10)
        return d is not None and not d.empty and "Close" in d.columns and d["Close"].dropna().size>0
    except Exception:
        return False

def hisse_listesine_ekle(kod):
    kod=re.sub(r"[^A-Z0-9]","",str(kod).upper())
    if bist_kodu_gecerli_mi(kod) and kod not in HISSELER:
        HISSELER.append(kod)
        HISSELER.sort()
    return kod

def rsi_hesapla(close,period=14):
    delta=close.diff();gain=delta.clip(lower=0);loss=-delta.clip(upper=0)
    ag=gain.ewm(alpha=1/period,adjust=False).mean();al=loss.ewm(alpha=1/period,adjust=False).mean();rs=ag/al.replace(0,np.nan)
    return 100-(100/(1+rs))

def analiz_et(kod,gun,risk_esigi):
    df=veri_getir(kod,gun)
    if df.empty or len(df)<5:return None,df
    close=df["Close"].astype(float);fiyat=float(close.iloc[-1]);onceki=float(close.iloc[-2]);gunluk=((fiyat-onceki)/onceki)*100 if onceki else 0.0
    ma20=float(close.rolling(min(20,len(close))).mean().iloc[-1]);ma50=float(close.rolling(min(50,len(close))).mean().iloc[-1])
    rs=rsi_hesapla(close).dropna();rsi=float(rs.iloc[-1]) if len(rs) else 50.0
    ret=close.pct_change().dropna();vol=float(ret.std()*np.sqrt(252)*100) if len(ret)>1 else 0.0
    son20=df.tail(min(20,len(df)));destek=float(son20["Low"].min());direnc=float(son20["High"].max())
    tr=pd.concat([df["High"]-df["Low"],(df["High"]-df["Close"].shift()).abs(),(df["Low"]-df["Close"].shift()).abs()],axis=1).max(axis=1)
    atrs=tr.rolling(14).mean().dropna();atr=float(atrs.iloc[-1]) if len(atrs) else fiyat*0.02
    stop=max(0,fiyat-1.5*atr);hedef=fiyat+1.5*atr
    skor=50;skor+=12 if fiyat>ma20 else -12;skor+=10 if fiyat>ma50 else -10;skor+=8 if ma20>ma50 else -5
    if gunluk>=3:skor+=8
    elif gunluk>=1:skor+=5
    elif gunluk>0:skor+=2
    elif gunluk<=-3:skor-=10
    else:skor-=5
    if 52<=rsi<=65:skor+=10
    elif 45<=rsi<52:skor+=3
    elif 65<rsi<=72:skor+=4
    elif rsi>75:skor-=10
    elif rsi<30:skor-=5
    if vol>risk_esigi:skor-=8
    skor=int(max(0,min(100,skor)))
    sinyal="AL" if skor>=75 else "AL İZLE" if skor>=62 else "BEKLE" if skor>=42 else "ZAYIF / SAT"
    return {"kod":kod,"fiyat":fiyat,"gunluk":gunluk,"rsi":rsi,"ma20":ma20,"ma50":ma50,"volatilite":vol,"destek":destek,"direnc":direnc,"hedef":hedef,"stop":stop,"skor":skor,"sinyal":sinyal},df

