st.markdown(T("## 🏦 Kurum / Akıllı Para", "## 🏦 Institution / Smart Money"))
st.caption(T("Seçtiğin hisse için büyük aracı kurumların net alım/satım verilerini girerek Kurum Skoru oluşturur. Pozitif lot = net alım/toplama, negatif lot = net satış/azaltma.", "Enter major broker net buy/sell data for the selected stock to calculate an Institution Score. Positive lots = net buying/accumulation; negative lots = net selling/reduction."))

kh1,kh2=st.columns([2.2,1])
with kh1:
    kurum_hisse=st.text_input(T("Hisse Kodu", "Stock Code"),value="TUPRS",placeholder=T("Örnek: TUPRS, ASTOR, THYAO", "Example: TUPRS, ASTOR, THYAO"),key="kurum_hisse_kodu").strip().upper()
with kh2:
    st.markdown("<div style='height:28px'></div>",unsafe_allow_html=True)
    kurum_yukle=st.button(T("📊 Hisseyi Yükle", "📊 Load Stock"),type="primary",width="stretch",key="kurum_hisse_yukle")

if kurum_hisse:
    kurum_ticker=kurum_hisse if kurum_hisse in ABD else kurum_hisse+".IS"
    kurum_sonuc,_=analiz_et(kurum_ticker,zaman_penceresi,risk_esigi)
    if kurum_sonuc is not None:
        para="₺" if kurum_ticker.endswith(".IS") else "$"
        hk1,hk2,hk3=st.columns(3)
        hk1.metric(T("Seçili Hisse", "Selected Stock"),kurum_hisse)
        hk2.metric(T("Fiyat", "Price"),f'{para}{kurum_sonuc["fiyat"]:,.2f}',f'{kurum_sonuc["gunluk"]:+.2f}%')
        hk3.metric(T("ARNI Teknik Skoru", "ARNI Technical Score"),f'{kurum_sonuc["skor"]}/100')
    else:
        st.warning(T(f"{kurum_hisse} için fiyat verisi alınamadı. Kurum verilerini yine de elle girebilirsin.", f"Price data for {kurum_hisse} could not be retrieved. You can still enter institution data manually."))

with st.expander(T("Kurum verisi gir", "Enter institution data"), expanded=True):
    kurum_satirlari=[]
    varsayilanlar=["Citibank","Bank of America","İş Yatırım","Ak Yatırım","TEB","Tera Yatırım","Midas","Bulls"]
    for i,kurum in enumerate(varsayilanlar):
        c1,c2,c3=st.columns([2.2,1.4,1])
        with c1:
            ad=st.text_input(f"{T('Kurum', 'Institution')} {i+1}",value=kurum,key=f"kurum_ad_{i}")
        with c2:
            lot=st.number_input(f"{T('Lot değişimi', 'Lot change')} {i+1}",value=0.0,step=1000.0,format="%.0f",key=f"kurum_lot_{i}")
        with c3:
            tip=st.selectbox(f"{T('Tür', 'Type')} {i+1}",["takas","akd"],key=f"kurum_tip_{i}")
        if ad.strip() and lot!=0:
            kurum_satirlari.append({"kurum":ad,"degisim_lot":lot,"tip":tip})

    kskor,kdurum,kdetay=kurum_skoru_hesapla(kurum_satirlari)
    toplam_net=int(sum(x["degisim_lot"] for x in kurum_satirlari)) if kurum_satirlari else 0
    kc1,kc2,kc3=st.columns(3)
    kc1.metric(T("Kurum Skoru", "Institution Score"),f"{kskor}/100")
    kc2.metric(T("Akıllı Para", "Smart Money"),smart_money_text(kdurum))
    kc3.metric(T("Toplam Net Lot", "Total Net Lots"),f"{toplam_net:,.0f}".replace(",","."))
    teknik_skor=kurum_sonuc["skor"] if 'kurum_sonuc' in locals() and kurum_sonuc is not None else 50
    if kskor>=75 and teknik_skor>=70 and toplam_net>0:
        kurum_karar="AL"
    elif kskor>=60 and toplam_net>0:
        kurum_karar="AL İZLE" if teknik_skor>=62 else "BEKLE"
    elif kskor>=45:
        kurum_karar="BEKLE"
    else:
        kurum_karar="ZAYIF / SAT"
    if 60 <= kskor < 75 and toplam_net>0 and teknik_skor<62:
        st.info(f"🏦 {T('Kurum Kararı', 'Institution Decision')}: {T('POZİTİF / İZLE', 'POSITIVE / WATCH')} · {T('Kurum', 'Institution')} {kskor}/100 · {T('Teknik', 'Technical')} {teknik_skor}/100")
    else:
        arni_sinyal_panel(kurum_karar, prefix=T("Kurum + Teknik Kararı", "Institution + Technical Decision"))
    if kurum_satirlari:
        tablo=[]
        for kurum,lot,agir,katki in kdetay:
            yon=T("Alım", "Buy") if lot>0 else T("Satış", "Sell")
            tablo.append({T("Hisse", "Stock"):kurum_hisse or "-",T("Kurum", "Institution"):kurum,T("Lot Değişimi", "Lot Change"):int(lot),T("Tür", "Type"):"takas/akd",T("Yön", "Direction"):yon,T("Ağırlık", "Weight"):round(agir,2),T("Etki", "Impact"):round(katki,3)})
        st.dataframe(pd.DataFrame(tablo),width="stretch",hide_index=True)
        alicilar=sorted([(kurum,lot) for kurum,lot,agir,katki in kdetay if lot>0],key=lambda x:x[1],reverse=True)
        if alicilar:
            guclu=", ".join([f"{k} +{int(l):,}".replace(",",".") for k,l in alicilar[:3]])
            st.success(f"💰 {T('En güçlü alıcılar', 'Strongest buyers')}: {guclu}")
    else:
        st.info(T("Örnek: TUPRS seç → Citibank +250000, BofA +180000, İş Yatırım -120000, Ak Yatırım -80000 gir. Pozitif değer alım, negatif değer satımdır.", "Example: Select TUPRS → enter Citibank +250000, BofA +180000, İş Yatırım -120000, Ak Yatırım -80000. Positive values are buys; negative values are sells."))

st.markdown("---");st.markdown(T("## 🤖 ARNI'ye Sor", "## 🤖 Ask ARNI"));st.caption(T("Hisse senetleri hakkında sorun; teknik göstergeleri özetleyeyim. Tüm geçerli BIST hisse kodları desteklenir.", "Ask about stocks and I will summarize the technical indicators. All valid BIST stock codes are supported."))
q1,q2=st.columns([5,1])
with q1:soru=st.text_input(T("ARNI sorusu", "ARNI question"),placeholder=T("Ör: ASTOR alınır mı? TUPRS gidişatı nasıl? THYAO teknik analiz...", "Example: Is ASTOR a buy? How is TUPRS trending? THYAO technical analysis..."),key="arni_soru_alt",label_visibility="collapsed")
with q2:sor_buton=st.button(T("Gönder", "Send"),type="primary",key="arni_gonder")
if sor_buton and soru.strip():
    lower=soru.lower();bulunan=None
    for isim,ticker in ISIM_SOZLUGU.items():
        if isim in lower:bulunan=ticker;break
    if bulunan is None:
        # Her geçerli BIST kodunu kabul et; sadece sabit HISSELER listesiyle sınırlama yok.
        # Böylece listede olmayan yeni/diğer BIST hisseleri de ARNI tarafından analiz edilir.
        for token in re.findall(r"\b[A-Z0-9]{3,8}\b",soru.upper()):
            if token not in {"ARNI", "ALINIR", "SATILIR", "HISSE", "HİSSE", "ANALIZ", "ANALİZ"}:
                bulunan=token
                break
    if bulunan is None:st.warning(T("Soruda bir hisse kodu bulamadım. Örnek: ASTOR, TUPRS, THYAO.", "I could not find a stock code in the question. Example: ASTOR, TUPRS, THYAO."))
    else:
        soru_kod=bulunan if bulunan in ABD else bulunan+".IS";soru_sonuc,_=analiz_et(soru_kod,zaman_penceresi,risk_esigi)
        if soru_sonuc is None:st.error(T(f"{bulunan} için veri alınamadı.", f"Data for {bulunan} could not be retrieved."))
        else:
            para="₺" if soru_kod.endswith(".IS") else "$";st.markdown(f"### {bulunan} {T('Analizi', 'Analysis')}")
            a,b,c,d=st.columns(4);a.metric(T("Fiyat", "Price"),f'{para}{soru_sonuc["fiyat"]:,.2f}',f'{soru_sonuc["gunluk"]:+.2f}%');b.metric(T("ARNI Skoru", "ARNI Score"),f'{soru_sonuc["skor"]}/100');c.metric("RSI",f'{soru_sonuc["rsi"]:.1f}');d.metric(T("Volatilite", "Volatility"),f'%{soru_sonuc["volatilite"]:.1f}')
            arni_sinyal_panel(soru_sonuc["sinyal"])
            st.markdown(f'<div style="margin-top:14px;font-size:18px;font-weight:800;line-height:1.8">'
                        f'🟦 {T("Destek", "Support")} <strong>{para}{soru_sonuc["destek"]:,.2f}</strong> &nbsp;·&nbsp; '
                        f'🟧 {T("Direnç", "Resistance")} <strong>{para}{soru_sonuc["direnc"]:,.2f}</strong> &nbsp;·&nbsp; '
                        f'🎯 {T("Hedef", "Target")} <strong>{para}{soru_sonuc["hedef"]:,.2f}</strong> &nbsp;·&nbsp; '
                        f'🛑 Stop <strong>{para}{soru_sonuc["stop"]:,.2f}</strong></div>',unsafe_allow_html=True)

